mapper.select:
SELECT D.DEPT_CD, D.DEPT_NM, D.UP_DEPT_CD, U.DEPT_NM AS UP_DEPT_NM, D.SORT_ORD, D.USE_YN FROM TB_DEPT D LEFT JOIN TB_DEPT U ON U.DEPT_CD = D.UP_DEPT_CD
AND D.DEPT_NM LIKE '%' || #{deptNm} || '%' AND D.USE_YN = #{useYn}
ORDER BY D.SORT_ORD, D.DEPT_CD

update.foreach:
UPDATE TB_DEPT
   SET SORT_ORD = #{row.sortOrd}
 WHERE DEPT_CD = #{row.deptCd}
